  fs.symlinkSync(process.execPath, path.join(dir, "node"));
  for (const t of ["env", "bash", "sh", "git", "dirname", "ls", "cat", "grep", "printf", "rm", "mkdir"]) {
    const found = execSync(`command -v ${t} || true`, { shell: "/bin/sh" }).toString().trim();
