import { isolateEvalCommandHome, runVersionedEvalCommand } from "./eval_cli.js";
import { redactDiagnosticForOutput } from "./core/persistence_protection.js";
import { formatDiagnosticForOutput } from "./ui.js";
import { streamEventSink, streamObserver } from "./stream_json.js";

function collectDeliverableFile(value: string, previous: string[] = []): string[] {
  return [...previous, value];
}

/** Configuration errors (unknown provider, missing model or base URL) end the command with a message, not a trace. */
function buildConfig(options: any): HarnessConfig {
  try {
    return buildConfigOrThrow(options);
    const originalWarn = console.warn;
    const originalError = console.error;
    const originalStdoutWrite = process.stdout.write.bind(process.stdout);

    if (shouldCapture) {
      console.log = (...args: any[]) => {
        capturedLogs.push(args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
      };
      console.warn = (...args: any[]) => {
        capturedLogs.push("[WARN] " + args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
      };
      console.error = (...args: any[]) => {
        capturedLogs.push("[ERROR] " + args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
      };
      // Streamed model tokens are written with process.stdout.write; capture them too so --json stdout is only the JSON document.
      (process.stdout as any).write = (chunk: any, encoding?: any, cb?: any): boolean => {
        capturedLogs.push(typeof chunk === "string" ? chunk : Buffer.from(chunk).toString("utf-8"));
        const done = typeof encoding === "function" ? encoding : cb;
        if (typeof done === "function") done();
        return true;
      };
    }

    let taskError: Error | undefined;
    let turn: TurnResult | undefined;
    if (options.observer) this.agent.setObserver(options.observer);
    try {
      turn = await this.agent.run(prompt, options.onConfirm, {
        signal: options.signal,
        resume: Boolean(options.resumeTaskId),
        step: Boolean(options.step),
      });
    } catch (err: any) {
      taskError = err;
    } finally {
      if (options.observer) this.agent.setObserver(undefined);
      if (shouldCapture) {
        console.log = originalLog;
        console.warn = originalWarn;
        console.error = originalError;
        process.stdout.write = originalStdoutWrite as typeof process.stdout.write;
      }
    }

    const finalTurn: TurnResult = turn ?? failedTurnFromError(taskError, this.config.maxSteps, this.agent.hasUnverifiedChanges());
